\node[above left,xshift=-1pt,yshift=2pt,text=black] at (0,{1.75*\circleradius}) {$y$};
\begin{scope}[every node/.style={font=\fontsize{8.5}{10.2}\selectfont,text=black}]
\node[below left=2pt] at ({-\circleradius},0) {\special{dvisvgm:raw <g data-graph-text="tick">}$-\sqrt{20}$\special{dvisvgm:raw </g>}};
\node[below right=2pt] at (\circleradius,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$\sqrt{20}$\special{dvisvgm:raw </g>}};
\node[left=3pt] at (0,\circleradius) {\special{dvisvgm:raw <g data-graph-text="tick">}$\sqrt{20}$\special{dvisvgm:raw </g>}};
